insert into public.recipe_versions values('alfredo',1,true,true,'{"id":"alfredo","version":1,"name":"پنه آلفردو","description":"پاستای خامه‌ای با مرغ و قارچ","servings":4,"minutes":60,"difficulty":"آسان","category":"پاستا","ingredients":[{"ingredientId":"penne","quantity":400,"unit":"g","estimated":true,"optional":false},{"ingredientId":"chicken","quantity":300,"unit":"g","estimated":true,"optional":false},{"ingredientId":"mushroom","quantity":200,"unit":"g","estimated":true,"optional":false},{"ingredientId":"garlic","quantity":8,"unit":"g","estimated":true,"optional":false},{"ingredientId":"cream","quantity":200,"unit":"g","estimated":false,"optional":false},{"ingredientId":"milk","quantity":200,"unit":"ml","estimated":true,"optional":false},{"ingredientId":"parmesan","quantity":60,"unit":"g","estimated":true,"optional":false},{"ingredientId":"butter","quantity":25,"unit":"g","estimated":true,"optional":false},{"ingredientId":"thyme","quantity":2,"unit":"g","estimated":true,"optional":false},{"ingredientId":"salt","quantity":3,"unit":"g","estimated":true,"optional":false},{"ingredientId":"pepper","quantity":1,"unit":"g","estimated":true,"optional":false}],"steps":["پنه را در آب جوش بپزید و آبکش کنید.","مرغ و سیر را تفت دهید؛ قارچ را با کره جداگانه تفت دهید.","شیر و خامه را اضافه کنید و سپس پنیر و پنه را با سس مخلوط کنید."],"sourceUrl":"https://kalleh.com/book/recipe/%D8%B7%D8%B1%D8%B2-%D8%AA%D9%87%DB%8C%D9%87-%D9%BE%D8%A7%D8%B3%D8%AA%D8%A7-%D8%B1%D8%B3%D8%AA%D9%88%D8%B1%D8%A7%D9%86%DB%8C/","sourceStatus":"reviewed","note":"مقادیر تبدیل‌شده به گرم و میلی‌لیتر و زمان کل، برآورد اولیه قابل اصلاح هستند؛ وزن عدد و حجم پیمانه از منبع اندازه‌گیری نشده است. تصویر، تصویرسازی برنامه است.","published":true,"art":"پاستا"}'::jsonb) on conflict(recipe_id,version) do nothing;
